#region "Imports"
using System.Collections.Generic;
using UnityEngine;
#endregion


namespace RoadCityMaster.City
{
    /// <summary> The street-network stage's first operator (section 10.4): the roads-first, functional
    /// classification street layer, generated by the extended L-system of Parish &amp; Müller,
    /// "Procedural Modeling of Cities" (SIGGRAPH 2001). The paper is the named baseline RM-09 is
    /// required to follow rather than invent: a growing front of proposed street segments, each
    /// checked against local constraints and then accepted, adjusted, or rejected.
    ///
    /// The constraint check has THREE parts, and it reports WHICH one rejected a segment:
    ///   1. TERRAIN  -- the gradient between the segment's ends, sampled through the input's
    ///      <see cref="IPCGDataProvider"/>, must not exceed the class's <see cref="RoadClass.maxGradient"/>.
    ///   2. COLLISION -- the segment must not cross an existing edge it cannot be snapped into.
    ///   3. GEOMETRY  -- the turn against the segment's predecessor must not be sharper than the
    ///      class's <see cref="RoadClass.minCurveRadius"/> permits for its segment length.
    /// A rejection on any of the three is tallied by reason in the <see cref="StreetNetworkReport"/>,
    /// because a network that silently refuses to grow one way is otherwise impossible to debug.
    ///
    /// It is a pure <see cref="CityOperator{TIn,TOut}"/>: no scene access (the terrain arrives as
    /// input), no unseeded randomness (every choice is derived from the operator seed through
    /// <see cref="CitySeed.ForItem"/>), so re-running it with the same input, parameters, and seed
    /// produces a byte-identical network. That is RM-09's determinism gate. </summary>
    [CreateAssetMenu(fileName = "StreetNetworkOperator",
                     menuName = "Road City Master/Operators/Street Network", order = 10)]
    public sealed class StreetNetworkOperator : CityOperator<StreetNetworkInput, StreetNetwork>
    {
        /// <summary> The functional classification this generation draws its road classes from. </summary>
        public RoadClassCatalog catalog;

        /// <summary> Hard cap on accepted edges, so a bad parameter set cannot grow without bound. </summary>
        public int maxSegments = 2000;

        /// <summary> Maximum deviation, in degrees, the terrain-following search may bend a segment
        /// away from its incoming direction while looking for the flattest continuation. </summary>
        [Range(0f, 80f)]
        public float terrainFollowAngle = 22f;

        /// <summary> How many candidate directions within <see cref="terrainFollowAngle"/> the search
        /// tests per proposal; the flattest legal one wins. </summary>
        [Range(1, 15)]
        public int terrainSamples = 7;

        /// <summary> How far a local street runs, in segments, before it stops. Locals fill blocks;
        /// they are not meant to cross the whole city, so they bound themselves. </summary>
        [Range(1, 40)]
        public int localMaxSteps = 6;

        /// <summary> A small seeded bend, in degrees, applied to each proposal's base direction before
        /// the terrain-follow search. It is what makes two different seeds produce genuinely different
        /// cities rather than the same layout rotated; being derived from the seed keeps it
        /// deterministic. </summary>
        [Range(0f, 30f)]
        public float organicJitter = 8f;


        /// <summary> One pending segment on the growth front. </summary>
        private struct Proposal
        {
            public int fromNode;          // index of the node this segment grows from
            public Vector2 dir;           // XZ unit direction it grows in
            public int roadClassId;       // the class to realise it as
            public int stepsLeft;         // remaining segments before this stroke stops (locals only)
            public float distSinceBranch; // metres since this stroke last spawned a branch
        }


        /// <summary> Grows the network from a seeded arterial cross at the region centre, breadth
        /// first. FIFO processing plus per-proposal seeding make the result a function of nothing but
        /// the input, the parameters, and the seed. </summary>
        public override StreetNetwork Execute(StreetNetworkInput input, int operatorSeed)
        {
            StreetNetwork net = new StreetNetwork();
            if (catalog == null || input == null)
            {
                return net;
            }

            RoadClass arterial = catalog.Get(RoadClassCatalog.ArterialId);
            if (arterial == null)
            {
                return net;
            }

            Queue<Proposal> front = new Queue<Proposal>();
            Vector2 centre = input.regionXZ.center;
            int centreNode = net.AddNodeSnapped(OnSurface(input, centre.x, centre.y), arterial.SnapDistance, out _);
            EnqueueSeedArms(front, centreNode, Random01(operatorSeed, 0) * 90f, arterial);

            int proposalId = 0;
            while (front.Count > 0 && net.edges.Count < maxSegments)
            {
                GrowOne(net, input, front.Dequeue(), CitySeed.ForItem(operatorSeed, proposalId++), front);
            }

            return net;
        }

        /// <summary> Enqueues four arterial arms from the seed node, at the seeded axis and its three
        /// right-angle rotations -- the arterial cross the rest of the city hangs off. </summary>
        private void EnqueueSeedArms(Queue<Proposal> front, int node, float axisDegrees, RoadClass arterial)
        {
            for (int arm = 0; arm < 4; arm++)
            {
                float radians = (axisDegrees + 90f * arm) * Mathf.Deg2Rad;
                Vector2 dir = new Vector2(Mathf.Cos(radians), Mathf.Sin(radians));
                front.Enqueue(new Proposal
                {
                    fromNode = node, dir = dir, roadClassId = arterial.id,
                    stepsLeft = int.MaxValue, distSinceBranch = 0f
                });
            }
        }


        /// <summary> Realises one proposal: adjust it to the terrain, run the three-part local
        /// constraint check, and on acceptance snap, commit the edge, and schedule its continuation
        /// and branches. Every rejection is tallied by reason. </summary>
        private void GrowOne(StreetNetwork net, StreetNetworkInput input, Proposal p, int seed, Queue<Proposal> front)
        {
            net.report.proposed++;
            RoadClass rc = catalog.Get(p.roadClassId);
            if (rc == null)
            {
                return;
            }

            Vector3 fromPos = net.nodes[p.fromNode].position;

            // ADJUST + part 1 (TERRAIN) and the region test, folded into the flattest-legal search.
            Vector2 chosenDir;
            Vector3 toPos;
            SegmentRejection reason;
            if (!ChooseContinuation(input, rc, fromPos, p.dir, seed, out chosenDir, out toPos, out reason))
            {
                net.report.Reject(reason);
                return;
            }

            // Part 3 (GEOMETRY): the turn against the incoming direction.
            if (Vector2.Angle(p.dir, chosenDir) > DeflectionLimitDegrees(rc))
            {
                net.report.Reject(SegmentRejection.Geometry);
                return;
            }

            // Part 2 (COLLISION): crossing an existing edge it does not already share a node with.
            if (CrossesExisting(net, p.fromNode, fromPos, toPos))
            {
                net.report.Reject(SegmentRejection.Collision);
                return;
            }

            bool reused;
            int toNode = net.AddNodeSnapped(toPos, rc.SnapDistance, out reused);
            if (!net.AddEdge(p.fromNode, toNode, p.roadClassId, rc.isDivided, rc.medianWidth))
            {
                return; // that pair already had an edge; nothing new to grow from
            }
            net.report.accepted++;

            if (!reused)
            {
                ScheduleGrowth(front, net, p, rc, chosenDir, toNode);
            }
        }


        /// <summary> After an edge is committed, schedules what grows from its new end: the stroke's
        /// own continuation, and -- for arterials and collectors that have run a class-spacing's worth
        /// of distance since their last branch -- a perpendicular child one class down. Locals never
        /// branch and stop after <see cref="localMaxSteps"/>; that is what makes them fill blocks
        /// rather than sprawl. </summary>
        private void ScheduleGrowth(Queue<Proposal> front, StreetNetwork net, Proposal p, RoadClass rc, Vector2 chosenDir, int toNode)
        {
            bool isLocal = rc.id == RoadClassCatalog.LocalId;
            float distSinceBranch = p.distSinceBranch + rc.segmentLength;

            // Decide the branch first, so the continuation carries the correct reset counter.
            int childId = -1;
            bool branchNow = !isLocal && distSinceBranch >= rc.targetSpacing && TryLowerClass(rc.id, out childId);

            // The stroke's own continuation. Locals count down; higher classes run until the region,
            // the segment cap, or a constraint stops them.
            if (!isLocal || p.stepsLeft > 1)
            {
                front.Enqueue(new Proposal
                {
                    fromNode = toNode, dir = chosenDir, roadClassId = rc.id,
                    stepsLeft = isLocal ? p.stepsLeft - 1 : int.MaxValue,
                    distSinceBranch = branchNow ? 0f : distSinceBranch
                });
            }

            // A perpendicular child one class down, on both sides of the parent.
            if (branchNow)
            {
                RoadClass child = catalog.Get(childId);
                if (child != null)
                {
                    bool childLocal = child.id == RoadClassCatalog.LocalId;
                    Vector2 side = Perp(chosenDir);
                    EnqueueBranch(front, toNode, side, child.id, childLocal);
                    EnqueueBranch(front, toNode, -side, child.id, childLocal);
                }
            }
        }

        /// <summary> Enqueues one branch proposal of the given class from a node in one direction. </summary>
        private void EnqueueBranch(Queue<Proposal> front, int fromNode, Vector2 dir, int roadClassId, bool isLocal)
        {
            front.Enqueue(new Proposal
            {
                fromNode = fromNode, dir = dir.normalized, roadClassId = roadClassId,
                stepsLeft = isLocal ? localMaxSteps : int.MaxValue,
                distSinceBranch = 0f
            });
        }

        /// <summary> The class one step down the hierarchy from <paramref name="parentId"/>: arterial
        /// branches collectors, collectors branch locals, locals branch nothing. </summary>
        private static bool TryLowerClass(int parentId, out int childId)
        {
            if (parentId == RoadClassCatalog.ArterialId) { childId = RoadClassCatalog.CollectorId; return true; }
            if (parentId == RoadClassCatalog.CollectorId) { childId = RoadClassCatalog.LocalId; return true; }
            childId = -1;
            return false;
        }

        /// <summary> The ADJUST step and part 1 (TERRAIN) of the constraint check, folded together. It
        /// applies a seeded organic bend to the incoming direction, fans <see cref="terrainSamples"/>
        /// candidate directions across &#177;<see cref="terrainFollowAngle"/> straightest-first, and
        /// returns the flattest candidate whose endpoint stays inside the region and whose gradient is
        /// within the class limit. Straightest-first ordering plus a strict &lt; on the gradient makes
        /// the least-deflected of two equally-flat candidates win, which keeps the choice deterministic.
        /// Reports <see cref="SegmentRejection.OutOfBounds"/> when every candidate leaves the region,
        /// or <see cref="SegmentRejection.Terrain"/> when some stay in but all are too steep. </summary>
        private bool ChooseContinuation(StreetNetworkInput input, RoadClass rc, Vector3 fromPos, Vector2 inDir,
            int seed, out Vector2 chosenDir, out Vector3 toPos, out SegmentRejection reason)
        {
            chosenDir = inDir;
            toPos = fromPos;

            // Seeded organic bend on the base direction; this is what makes two seeds diverge.
            float bend = (Random01(seed, 1) * 2f - 1f) * organicJitter;
            Vector2 baseDir = Rotate(inDir.normalized, bend);
            Vector2 fromXZ = new Vector2(fromPos.x, fromPos.z);

            bool anyInBounds = false;
            bool found = false;
            float bestGradient = float.MaxValue;

            int count = Mathf.Max(1, terrainSamples);
            for (int i = 0; i < count; i++)
            {
                Vector2 dir = Rotate(baseDir, FanAngle(i, count) * terrainFollowAngle);
                Vector2 endXZ = fromXZ + dir * rc.segmentLength;
                if (!input.regionXZ.Contains(endXZ))
                {
                    continue;
                }
                anyInBounds = true;

                Vector3 end = OnSurface(input, endXZ.x, endXZ.y);
                float gradient = Gradient(fromPos, end);
                if (gradient <= rc.maxGradient && gradient < bestGradient)
                {
                    bestGradient = gradient;
                    chosenDir = dir;
                    toPos = end;
                    found = true;
                }
            }

            reason = found ? SegmentRejection.None
                   : anyInBounds ? SegmentRejection.Terrain
                   : SegmentRejection.OutOfBounds;
            return found;
        }

        /// <summary> The i-th fan offset in [-1, 1], emitted straightest-first: 0, then the nearest
        /// pair out to the extremes, so index 0 is dead ahead and later indices deflect more. </summary>
        private static float FanAngle(int i, int count)
        {
            int maxPair = count / 2;
            if (maxPair == 0)
            {
                return 0f;
            }
            int pairIndex = (i + 1) / 2;
            float magnitude = (float)pairIndex / maxPair;
            return (i % 2 == 1) ? magnitude : -magnitude;
        }

        /// <summary> Lifts an XZ point onto the terrain surface, or onto y=0 when no provider is given
        /// (the flat implied surface a test grows on). This is the operator's ONLY terrain read, and it
        /// goes through the input's provider -- never the scene -- which is what keeps it pure. </summary>
        private static Vector3 OnSurface(StreetNetworkInput input, float x, float z)
        {
            float y = input.terrain != null ? input.terrain.SampleHeight(x, z) : 0f;
            return new Vector3(x, y, z);
        }

        /// <summary> A deterministic float in [0, 1) for a given operator seed and integer key, via the
        /// shared <see cref="CitySeed"/> mixer (the next line names the engine random in a doc
        /// reference, not a call -- determinism-exempt for RM-18's smell test).
        /// No <see cref="UnityEngine.Random"/> ever enters the
        /// operator, so the same seed and key always yield the same value. </summary>
        private static float Random01(int seed, int key)
        {
            return (uint)CitySeed.ForItem(seed, key) / (float)uint.MaxValue;
        }

        /// <summary> The left-hand perpendicular of a 2D vector. </summary>
        private static Vector2 Perp(Vector2 v)
        {
            return new Vector2(-v.y, v.x);
        }

        /// <summary> Rotates a 2D vector counter-clockwise by an angle in degrees. </summary>
        private static Vector2 Rotate(Vector2 v, float degrees)
        {
            float r = degrees * Mathf.Deg2Rad;
            float c = Mathf.Cos(r);
            float s = Mathf.Sin(r);
            return new Vector2(v.x * c - v.y * s, v.x * s + v.y * c);
        }

        /// <summary> The largest turn, in degrees, a segment of the class's length may make and still
        /// hold its minimum curve radius: the central angle of a chord equal to the segment length on a
        /// circle of that radius. A zero or negative radius means no limit. </summary>
        private static float DeflectionLimitDegrees(RoadClass rc)
        {
            if (rc.minCurveRadius <= 0f)
            {
                return 180f;
            }
            float ratio = Mathf.Clamp01(rc.segmentLength / (2f * rc.minCurveRadius));
            return 2f * Mathf.Asin(ratio) * Mathf.Rad2Deg;
        }

        /// <summary> The gradient (rise/run) between two surface points: the absolute height change
        /// over the horizontal distance. A degenerate (zero-length) run reports an impassable gradient
        /// so it is rejected rather than accepted by accident. </summary>
        private static float Gradient(Vector3 a, Vector3 b)
        {
            float dy = Mathf.Abs(b.y - a.y);
            float dxz = new Vector2(b.x - a.x, b.z - a.z).magnitude;
            return dxz > 1e-4f ? dy / dxz : float.MaxValue;
        }

        /// <summary> Part 2 (COLLISION): whether the proposed segment crosses an existing edge it does
        /// not already share the growth node with. Edges incident to <paramref name="fromNode"/> are
        /// skipped -- they legitimately meet the proposal there -- and the test is a strict crossing in
        /// the XZ plane, so segments that merely touch at an endpoint (which snapping will turn into a
        /// junction) are not counted as collisions. </summary>
        private bool CrossesExisting(StreetNetwork net, int fromNode, Vector3 fromPos, Vector3 toPos)
        {
            Vector2 p1 = new Vector2(fromPos.x, fromPos.z);
            Vector2 p2 = new Vector2(toPos.x, toPos.z);
            for (int i = 0; i < net.edges.Count; i++)
            {
                NetworkEdge e = net.edges[i];
                if (e.a == fromNode || e.b == fromNode)
                {
                    continue; // shares the growth node; a meeting, not a crossing
                }
                Vector3 a3 = net.nodes[e.a].position;
                Vector3 b3 = net.nodes[e.b].position;
                if (Geometry2D.SegmentsProperlyCross(p1, p2, new Vector2(a3.x, a3.z), new Vector2(b3.x, b3.z)))
                {
                    return true;
                }
            }
            return false;
        }
    }
}
